package org.springframework.samples.petclinic.acceptance;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** The '<REGION>-<HASH8>' customer code and the values derived from it. */
class OwnerIdentityTests extends AcceptanceBase {

	/** '04XXXXXXXX' as generated by {@link #uniqueTelephone()}, normalized to E.164 '+614XXXXXXXX'. */
	private static String e164(String auMobile) {
		return "+61" + auMobile.substring(1);
	}

	@Test
	void customerCodeIsPostcodeRegionAndTelephoneLastNameHash() throws Exception {
		ObjectNode o = withPostcode(ownerNode());
		String expected = "NSW-" + shaHex(e164(o.get("telephone").asText()) + o.get("lastName").asText(), 8);

		JsonNode n = fetchOwner(createOwnerOk(o));

		assertThat(n.get("customerCode").asText()).isEqualTo(expected);
	}

	@Test
	void regionComesFromPostcode() throws Exception {
		ObjectNode o = knownOwner("Melbourne");

		JsonNode n = fetchOwner(createOwnerOk(o));

		assertThat(n.get("customerCode").asText()).startsWith("VIC-");
		assertThat(n.get("locality").asText()).isEqualTo("VIC");
	}

	@Test
	void regionFallsBackToCityThenUnknownWithoutPostcode() throws Exception {
		ObjectNode sydney = ownerNode();
		sydney.put("city", "Sydney");
		ObjectNode elsewhere = ownerNode();

		assertThat(fetchOwner(createOwnerOk(sydney)).get("customerCode").asText()).startsWith("NSW-");
		JsonNode unknown = fetchOwner(createOwnerOk(elsewhere));
		assertThat(unknown.get("customerCode").asText()).matches("UNKNOWN-[0-9A-F]{8}");
		assertThat(unknown.get("locality").asText()).isEqualTo("UNKNOWN");
